import '@angular/compiler';
import { provideZonelessChangeDetection } from '@angular/core';
import { createApplication } from '@angular/platform-browser';
import { Astylar } from 'astylarui';
import { cursorInput } from './cursor-default-input.mjs';

const query = new URLSearchParams(location.search), mode = query.get('mode'), name = query.get('case');
const translated = query.get('translated') === 'true', site = cursorInput(name);
document.body.style.cssText = 'margin:0;padding:0';
const stage = document.createElement(mode === 'reference' ? 'div' : 'canvas');
stage.id = 'audit-stage';
stage.style.cssText = `position:relative;display:block;width:240px;height:140px;left:${translated ? 64 : 0}px;top:${translated ? 40 : 0}px;margin:0;padding:0`;
document.body.append(stage);
let application, surface;
const publicEvents = [];
if (mode === 'reference') {
  const css = document.createElement('style');
  css.textContent = site.styles.map(({ selector, ...values }) => `${selector}{${Object.entries(values)
    .map(([k, v]) => `${k.replace(/[A-Z]/g, c => '-' + c.toLowerCase())}:${v}`).join(';')}}`).join('\n');
  document.head.append(css);
  function append(parent, description) {
    const node = document.createElement(description.type); node.id = description.id;

    if (description.type === 'input') {
      node.type = description.inputType;
      if (Object.hasOwn(description,'value')) node.value = description.value;
      if (Object.hasOwn(description,'name')) node.name = description.name;
      node.checked = description.checked ?? false;
      node.disabled = description.disabled ?? false;
      if(description.ariaLabel) node.setAttribute('aria-label',description.ariaLabel);
    } else node.textContent = description.textContent ?? description.value ?? '';
    parent.append(node);
    for (const child of description.children ?? []) append(node, child);
  }
  for (const child of site.root.children) append(stage, child);
} else if (mode === 'astylar') {
  application = await createApplication({ providers: [provideZonelessChangeDetection()] });
  surface = application.injector.get(Astylar).mount(stage, site, {
    diagnostics: { logLevel: 'silent' }, events: { onEvent: event => publicEvents.push({ ...event }) },
  });
  await surface.whenSettled();
} else throw new Error('Expected reference or astylar mode');

async function settle() {
  await document.fonts.ready; await surface?.whenSettled();
  await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
}
window.cursorDefaultAudit = {
  settle,

  controlDetails() {
    const native = mode === 'reference' ? document.getElementById('target') : null;
    const managed = surface?.host?.inputElementService?.getInputElement('target');
    return {native:native?{tag:native.tagName,type:native.type,value:native.value,
      valueAttribute:native.getAttribute('value'),checked:native.checked,disabled:native.disabled,
      textContent:native.textContent}:null,
      manager:managed?{type:managed.type,value:managed.value,checked:managed.checked,
        labelMesh:managed.labelMesh?{name:managed.labelMesh.name,visible:managed.labelMesh.isVisible}:null}:null};
  },
  snapshot(point) {
    const box = stage.getBoundingClientRect();
    const hit = document.elementFromPoint(point.x, point.y);
    const native = mode === 'reference' ? document.getElementById('target') : null;
    const style = native ? getComputedStyle(native) : null;
    const hitStyle = hit ? getComputedStyle(hit) : null;
    // The runner chooses a blank inset, but prove that it does not hit text
    // before interpreting CSS auto as the default arrow in the reference.
    let pointTouchesText = false;
    if (hit) {
      const walker = document.createTreeWalker(hit, NodeFilter.SHOW_TEXT);
      for (let node; (node = walker.nextNode());) {
        const range = document.createRange(); range.selectNodeContents(node);
        if ([...range.getClientRects()].some(r => point.x >= r.left && point.x <= r.right && point.y >= r.top && point.y <= r.bottom)) pointTouchesText = true;
      }
    }
    return { mode, name, translated, site: structuredClone(site), point,
      surfaceBox: { x: box.x, y: box.y, width: box.width, height: box.height },
      hit: { id: hit?.id ?? null, type: hit?.tagName.toLowerCase() ?? null, cursor: hitStyle?.cursor ?? null, pointTouchesText },
      target: native ? { cursor: style.cursor, pointerEvents: style.pointerEvents,
        box: { x: native.getBoundingClientRect().x, y: native.getBoundingClientRect().y,
          width: native.getBoundingClientRect().width, height: native.getBoundingClientRect().height } } : null,
      canvasCursor: mode === 'astylar' ? getComputedStyle(stage).cursor : null,
      resolved: surface?.inspectResolvedStyles() ?? null,
      publicEvents: [...publicEvents], diagnostics: surface?.diagnostics ?? null };
  },
  dispose() { surface?.dispose(); application?.destroy(); return { disposed: surface?.disposed ?? true }; },
};

export const cursorCases = ['button-omitted', 'button-default', 'button-pointer', 'button-hover',
  'button-parent', 'label-omitted', 'label-default', 'label-parent', 'div-parent'];

function baseCursorInput(name) {
  if (!cursorCases.includes(name)) throw new Error(`Unknown cursor case ${name}`);
  const [type, declaration] = name.split('-');
  return { root: { children: [{ type: 'div', id: 'parent', children: [{ type, id: 'target',
    ...(type === 'button' ? { value: 'Target' } : { textContent: 'Target' }) }] }] },
  styles: [
    { selector: '#parent', position: 'absolute', left: '20px', top: '32px', width: '180px', height: '72px',
      display: 'block', boxSizing: 'border-box', margin: '0', padding: '0', borderWidth: '0',
      background: '#eeeeee', ...(declaration === 'parent' ? { cursor: 'pointer' } : {}) },
    { selector: '#target', position: 'absolute', left: '16px', top: '16px', width: '140px', height: '40px',
      display: 'block', boxSizing: 'border-box', margin: '0', padding: '0', borderWidth: '0', borderRadius: '0',
      background: '#ffffff', color: '#111111', fontFamily: 'Arial', fontSize: '16px', lineHeight: '24px',
      ...(declaration === 'default' || declaration === 'pointer' ? { cursor: declaration } : {}) },
    ...(declaration === 'hover' ? [{ selector: '#target:hover', cursor: 'pointer' }] : []),
  ] };
}

export function cursorInput(name) {
  const [kind,variant] = name.split(':');
  if(!['radio','checkbox'].includes(kind)||!['omitted','value'].includes(variant)) throw new Error('Unknown control');
  const site=baseCursorInput('button-omitted');
  site.root.children[0].children=[{type:'input',inputType:kind,id:'target',name:'choice',
    checked:false,disabled:false,ariaLabel:'Choice',...(variant==='value'?{value:'VALUEONLY'}:{})}];
  Object.assign(site.styles[1],{width:'20px',height:'20px',appearance:'none',borderWidth:'2px',
    borderStyle:'solid',borderColor:'#111111',borderRadius:kind==='radio'?'50%':'0'});
  return site;
}
